/**
 * Managed-view visibility — who can see a saved list/calendar/kanban/dashboard/
 * agent view. Maps to HCL `user_ids` / `group_ids` on view resources (not
 * `elementum_access_policy`, which is record-level on the owning aspect).
 */
import type { AccessPolicyGroupRef, AccessPolicyUserRef } from "../access-policy/principal.js";
export interface ManagedViewSharing {
    readonly userIds?: readonly AccessPolicyUserRef[];
    readonly groupIds?: readonly AccessPolicyGroupRef[];
}
